const fs = require('fs');
const path = require('path');

function processDir(dir) {
  const files = fs.readdirSync(dir);
  for (const f of files) {
    const full = path.join(dir, f);
    if (fs.statSync(full).isDirectory()) {
      processDir(full);
    } else if (full.endsWith('.html')) {
      let content = fs.readFileSync(full, 'utf8');
      let changed = false;
      if (content.includes('../../../assets/images/')) {
        content = content.replaceAll('../../../assets/images/', '../../assets/images/');
        changed = true;
      }
      if (content.includes('../../../docs/documentation.html')) {
        content = content.replaceAll('../../../docs/documentation.html', '../../docs/documentation.html');
        changed = true;
      }
      if (content.includes('text-sm-left')) {
        content = content.replaceAll('text-sm-left', 'text-sm-start');
        changed = true;
      }
      if (content.includes('float-sm-right')) {
        content = content.replaceAll('float-sm-right', 'float-sm-end');
        changed = true;
      }
      if (changed) {
        fs.writeFileSync(full, content, 'utf8');
        console.log('Fixed:', full);
      }
    }
  }
}

processDir('polluxui-free/src/pages');
processDir('polluxui-free/dist/pages');
processDir('polluxui-free/src/partials');
"

